/*
 * <linux/ioctl.h>: how an ioctl request number is built. Most requests pack four things into 32
 * bits: whether the argument is read, written or both, the size of the argument in bytes, a letter
 * for the driver ('E' for input devices, 'P' for sound) and a number within it. The kernel checks
 * all four, so a request with the wrong size answers ENOTTY.
 *
 * Part of the x86 Runtime library, written for the editor in the shape of Linux's own header: the
 * same names, values and layouts, with only what the editor's devices use.
 *
 * Generated by scripts/sim-header/generate.mjs from scripts/sim-header/deviceTable.mjs. Do not edit
 * it: regenerate it.
 */
#ifndef _LINUX_IOCTL_H
#define _LINUX_IOCTL_H

#if !defined(__x86_64__)
#error "This <linux/ioctl.h> is the x86 one, included in a compilation for another Target"
#endif

#define _IOC_NRBITS    8
#define _IOC_TYPEBITS  8
#define _IOC_SIZEBITS  14
#define _IOC_DIRBITS   2
#define _IOC_NRMASK    ((1 << _IOC_NRBITS) - 1)
#define _IOC_TYPEMASK  ((1 << _IOC_TYPEBITS) - 1)
#define _IOC_SIZEMASK  ((1 << _IOC_SIZEBITS) - 1)
#define _IOC_DIRMASK   ((1 << _IOC_DIRBITS) - 1)
#define _IOC_NRSHIFT   0
#define _IOC_TYPESHIFT (_IOC_NRSHIFT + _IOC_NRBITS)
#define _IOC_SIZESHIFT (_IOC_TYPESHIFT + _IOC_TYPEBITS)
#define _IOC_DIRSHIFT  (_IOC_SIZESHIFT + _IOC_SIZEBITS)

/*
 * The direction, seen from the program: _IOC_READ means the kernel writes the argument for the
 * program to read.
 */
#define _IOC_NONE  0U /* No argument, or a plain number. */
#define _IOC_WRITE 1U /* The kernel reads the argument. */
#define _IOC_READ  2U /* The kernel writes the argument. */

/** A request number from its four parts. */
#define _IOC(dir, type, nr, size) (((dir) << _IOC_DIRSHIFT) | ((type) << _IOC_TYPESHIFT) | ((nr) << _IOC_NRSHIFT) | ((size) << _IOC_SIZESHIFT))

/** A request with no argument. */
#define _IO(type, nr) _IOC(_IOC_NONE, (type), (nr), 0)

/**
 * A request whose argument the kernel writes; size is its type, such as int. In NASM size is its
 * size in bytes, such as input_id_size.
 */
#define _IOR(type, nr, size) _IOC(_IOC_READ, (type), (nr), sizeof(size))

/** A request whose argument the kernel reads; size as for _IOR. */
#define _IOW(type, nr, size) _IOC(_IOC_WRITE, (type), (nr), sizeof(size))

/** A request whose argument the kernel reads and then writes back; size as for _IOR. */
#define _IOWR(type, nr, size) _IOC(_IOC_READ | _IOC_WRITE, (type), (nr), sizeof(size))

/* The four parts of a request number, taken apart again. */
#define _IOC_DIR(nr) (((nr) >> _IOC_DIRSHIFT) & _IOC_DIRMASK)
#define _IOC_TYPE(nr) (((nr) >> _IOC_TYPESHIFT) & _IOC_TYPEMASK)
#define _IOC_NR(nr) (((nr) >> _IOC_NRSHIFT) & _IOC_NRMASK)
#define _IOC_SIZE(nr) (((nr) >> _IOC_SIZESHIFT) & _IOC_SIZEMASK)

#endif
